const SpriteEntry *sprite_get(uint16_t pid, uint8_t kind)
{
    for (unsigned i = 0; i < SPRITE_COUNT; i++) {
        if (kSpriteTable[i].id == pid && kSpriteTable[i].kind == kind) {
            return &kSpriteTable[i];
        }
    }
    return NULL;
}
